"""Demo: the Pisano period equals the order of M in GL_2(Z/mZ)."""
from __future__ import annotations
from typing import Tuple

Matrix = Tuple[int, int, int, int]
M: Matrix = (1, 1, 1, 0)

def mul(x: Matrix, y: Matrix, m: int) -> Matrix:
    a, b, c, d = x; e, f, g, h = y
    return ((a*e+b*g) % m, (a*f+b*h) % m, (c*e+d*g) % m, (c*f+d*h) % m)

def operator_order(m: int) -> int:
    if m == 1:
        return 1
    ident = (1 % m, 0, 0, 1 % m)
    p, steps = M, 1
    while p != ident:
        p = mul(p, M, m); steps += 1
    return steps

if __name__ == "__main__":
    for m in range(1, 21):
        print(f"m={m:2d}  order(M mod m)=pi(m)={operator_order(m)}")

"""Demo: distant correlation F_N mod m via O(log N) operator powering."""
from __future__ import annotations
from typing import Tuple

Matrix = Tuple[int, int, int, int]
M: Matrix = (1, 1, 1, 0)

def mul(x: Matrix, y: Matrix, m: int) -> Matrix:
    a, b, c, d = x; e, f, g, h = y
    return ((a*e+b*g) % m, (a*f+b*h) % m, (c*e+d*g) % m, (c*f+d*h) % m)

def mat_pow(x: Matrix, n: int, m: int) -> Matrix:
    r = (1 % m, 0, 0, 1 % m); base = x
    while n:
        if n & 1: r = mul(r, base, m)
        base = mul(base, base, m); n >>= 1
    return r

def fib_mod(k: int, m: int) -> int:
    return 0 if k == 0 else mat_pow(M, k + 1, m)[3]

if __name__ == "__main__":
    m = 1_000_000_007
    for N in [10, 10**6, 10**18]:
        print(f"F_{N} mod {m} = {fib_mod(N, m)}")

"""Demo: verify primitivity of prime divisors at prime indices."""
from __future__ import annotations
from math import isqrt
from typing import List, Tuple

Matrix = Tuple[int, int, int, int]
M: Matrix = (1, 1, 1, 0)

def mul(x, y):
    a,b,c,d=x; e,f,g,h=y
    return (a*e+b*g, a*f+b*h, c*e+d*g, c*f+d*h)

def mat_pow(n: int) -> Matrix:
    r=(1,0,0,1); base=M
    while n:
        if n&1: r=mul(r,base)
        base=mul(base,base); n>>=1
    return r

def fib(k: int) -> int:
    return 0 if k==0 else mat_pow(k+1)[3]

def primes(n: int) -> List[int]:
    fs=[]; d=2
    while d<=isqrt(n):
        if n%d==0:
            fs.append(d)
            while n%d==0: n//=d
        d+=1
    if n>1: fs.append(n)
    return fs

if __name__ == "__main__":
    for n in [13,17,19,23,29,31]:
        fn=fib(n)
        for p in primes(fn):
            prim = all(fib(k)%p!=0 for k in range(1,n))
            print(f"n={n} prime factor {p} of F_n primitive? {prim}")

